import { useMemo } from "react";

export default function OutilsPage() {
  const tools = useMemo(
    () => [
      {
        id: "excel-succursale-epic",
        title: "Outil – Succursale EPIC",
        description: "Outil Excel pour la gestion des succursales dans EPIC.",
        // ⚠️ espaces encodés
        href: "/outils/Outil%20-%20Succursale%20EPIC.xlsx",
      },
    ],
    []
  );

  const openTool = (tool) => {
    const a = document.createElement("a");
    a.href = tool.href;
    a.download = "Outil - Succursale EPIC.xlsx"; // nom propre au téléchargement
    document.body.appendChild(a);
    a.click();
    a.remove();
  };

  return (
    <div className="p-10">
      <h1 className="text-3xl font-bold mb-6 text-blue-700">🧰 Outils</h1>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {tools.map((tool) => (
          <div key={tool.id} className="border rounded-lg p-4 bg-gray-50">
            <h2 className="text-lg font-semibold">{tool.title}</h2>
            <p className="text-sm text-gray-600 mt-1 mb-4">
              {tool.description}
            </p>

            <button
              onClick={() => openTool(tool)}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded transition"
            >
              📥 Ouvrir / Télécharger
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
